-- =============================================================================================
-- Hand-written (Prisma cannot express these). Asserted by test/integration/schema-catalog.int-spec.ts.
-- =============================================================================================

-- --- Shared trigger functions --------------------------------------------------------------

-- Append-only tables (schema-design §1.5): no UPDATE or DELETE, ever.
CREATE FUNCTION forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only (% refused)', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
END
$$;

-- Effective-dated versions (ADR-0005): decided rows are immutable; only drafts may be deleted.
CREATE FUNCTION forbid_decided_version_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION '% row % is % and cannot be deleted', TG_TABLE_NAME, OLD.id, OLD.status USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.status IN ('approved', 'rejected', 'withdrawn') THEN
    RAISE EXCEPTION '% row % is % and cannot be changed', TG_TABLE_NAME, OLD.id, OLD.status USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;

-- --- Partitions (schema-design §1.7) --------------------------------------------------------

-- Creates monthly partitions partitions.<table>_YYYY_MM for `months` months from `from_month`.
-- Idempotent; the worker calls it monthly (repeatable job registered in B1.3).
CREATE FUNCTION ensure_monthly_partitions(parent regclass, from_month date, months integer)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  base_name text := (SELECT relname FROM pg_class WHERE oid = parent);
  first_month date := date_trunc('month', from_month)::date;
  lower_month date;
  child text;
BEGIN
  FOR i IN 0 .. months - 1 LOOP
    lower_month := (first_month + make_interval(months => i))::date;
    child := format('%s_%s', base_name, to_char(lower_month, 'YYYY_MM'));
    IF to_regclass(format('partitions.%I', child)) IS NULL THEN
      -- Boundaries are UTC month starts (timestamps are stored in UTC).
      EXECUTE format('CREATE TABLE partitions.%I PARTITION OF %s FOR VALUES FROM (%L) TO (%L)',
                     child, parent,
                     lower_month::timestamp AT TIME ZONE 'UTC',
                     (lower_month + interval '1 month')::timestamp AT TIME ZONE 'UTC');
    END IF;
  END LOOP;
END
$$;

-- Safety net: rows outside the created months land here instead of failing (monitored in B1.3).
CREATE TABLE partitions.audit_logs_default PARTITION OF audit_logs DEFAULT;
CREATE TABLE partitions.activity_logs_default PARTITION OF activity_logs DEFAULT;
SELECT ensure_monthly_partitions('audit_logs', DATE '2026-09-01', 13);
SELECT ensure_monthly_partitions('activity_logs', DATE '2026-09-01', 13);

-- --- entities ------------------------------------------------------------------------------
ALTER TABLE entities
  ADD CONSTRAINT ck_entities__base_currency CHECK (base_currency = 'THB'),
  ADD CONSTRAINT ck_entities__fiscal_year_start_month CHECK (fiscal_year_start_month BETWEEN 1 AND 12),
  ADD CONSTRAINT ck_entities__code CHECK (code ~ '^[A-Z][A-Z0-9_]{1,15}$');

-- --- settings & versions (ADR-0005) --------------------------------------------------------
CREATE UNIQUE INDEX ux_settings__key__scope ON settings (key, scope_type, COALESCE(scope_id, 0));
ALTER TABLE settings
  ADD CONSTRAINT ck_settings__scope CHECK ((scope_type = 'platform') = (scope_id IS NULL)),
  ADD CONSTRAINT ck_settings__key CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  -- Traceability: every setting cites the decision / ADR it implements (CLAUDE.md).
  ADD CONSTRAINT ck_settings__decision_refs CHECK (cardinality(decision_refs) >= 1);

ALTER TABLE setting_versions
  ADD CONSTRAINT ck_setting_versions__version_no CHECK (version_no > 0),
  ADD CONSTRAINT ck_setting_versions__reason CHECK (btrim(reason) <> ''),
  ADD CONSTRAINT ck_setting_versions__decided CHECK (status NOT IN ('approved', 'rejected') OR decided_at IS NOT NULL);
CREATE TRIGGER tg_setting_versions__immutable BEFORE UPDATE OR DELETE ON setting_versions
  FOR EACH ROW EXECUTE FUNCTION forbid_decided_version_change();

-- --- approval engine (ADR-0006) ------------------------------------------------------------
ALTER TABLE approval_policies
  ADD CONSTRAINT ck_approval_policies__key CHECK (key ~ '^[a-z][a-z0-9_]*$');

ALTER TABLE approval_policy_versions
  ADD CONSTRAINT ck_approval_policy_versions__version_no CHECK (version_no > 0),
  ADD CONSTRAINT ck_approval_policy_versions__reason CHECK (btrim(reason) <> ''),
  ADD CONSTRAINT ck_approval_policy_versions__decided CHECK (status NOT IN ('approved', 'rejected') OR decided_at IS NOT NULL);
CREATE TRIGGER tg_approval_policy_versions__immutable BEFORE UPDATE OR DELETE ON approval_policy_versions
  FOR EACH ROW EXECUTE FUNCTION forbid_decided_version_change();

ALTER TABLE approval_steps
  ADD CONSTRAINT ck_approval_steps__step_no CHECK (step_no > 0),
  ADD CONSTRAINT ck_approval_steps__quorum CHECK (quorum >= 1),
  ADD CONSTRAINT ck_approval_steps__sla_minutes CHECK (sla_minutes IS NULL OR sla_minutes > 0);

-- Steps belong to their version: frozen once the version is decided.
CREATE FUNCTION approval_steps_follow_version() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  version_status config_version_status;
BEGIN
  SELECT status INTO version_status FROM approval_policy_versions
   WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.policy_version_id ELSE NEW.policy_version_id END;
  IF version_status IN ('approved', 'rejected', 'withdrawn') THEN
    RAISE EXCEPTION 'approval steps of a % policy version cannot change', version_status USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;
CREATE TRIGGER tg_approval_steps__follow_version BEFORE INSERT OR UPDATE OR DELETE ON approval_steps
  FOR EACH ROW EXECUTE FUNCTION approval_steps_follow_version();

ALTER TABLE approval_requests
  ADD CONSTRAINT ck_approval_requests__amount CHECK (amount IS NULL OR amount >= 0),
  ADD CONSTRAINT ck_approval_requests__pct CHECK (pct IS NULL OR pct >= 0),
  ADD CONSTRAINT ck_approval_requests__decided CHECK (status = 'pending' OR decided_at IS NOT NULL);

ALTER TABLE approval_request_steps
  ADD CONSTRAINT ck_approval_request_steps__step_no CHECK (step_no > 0),
  ADD CONSTRAINT ck_approval_request_steps__quorum CHECK (quorum >= 1);

-- Maker-checker (ADR-0006): the requester never approves, not even through a delegation.
CREATE FUNCTION approval_actions_maker_checker() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  requester bigint;
BEGIN
  IF NEW.action = 'approve' THEN
    SELECT requester_user_id INTO requester FROM approval_requests WHERE id = NEW.request_id;
    IF NEW.actor_user_id = requester OR NEW.on_behalf_of_user_id = requester THEN
      RAISE EXCEPTION 'the requester cannot approve their own request' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_approval_actions__maker_checker BEFORE INSERT ON approval_actions
  FOR EACH ROW EXECUTE FUNCTION approval_actions_maker_checker();
CREATE TRIGGER tg_approval_actions__append_only BEFORE UPDATE OR DELETE ON approval_actions
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

ALTER TABLE approval_delegations
  ADD CONSTRAINT ck_approval_delegations__window CHECK (valid_to > valid_from),
  ADD CONSTRAINT ck_approval_delegations__distinct CHECK (delegator_user_id <> delegate_user_id);

