ALTER TABLE audit_logs ADD CONSTRAINT ck_audit_logs__actor CHECK (
  (actor_type = 'user' AND actor_user_id IS NOT NULL AND actor_api_client_id IS NULL) OR
  (actor_type = 'api_client' AND actor_api_client_id IS NOT NULL AND actor_user_id IS NULL) OR
  (actor_type IN ('system', 'webhook') AND actor_user_id IS NULL AND actor_api_client_id IS NULL));
ALTER TABLE activity_logs ADD CONSTRAINT ck_activity_logs__actor CHECK (
  (actor_type = 'user' AND actor_user_id IS NOT NULL AND actor_api_client_id IS NULL) OR
  (actor_type = 'api_client' AND actor_api_client_id IS NOT NULL AND actor_user_id IS NULL) OR
  (actor_type IN ('system', 'webhook') AND actor_user_id IS NULL AND actor_api_client_id IS NULL));
ALTER TABLE domain_events ADD CONSTRAINT ck_domain_events__actor CHECK (
  (actor_type = 'user' AND actor_user_id IS NOT NULL AND actor_api_client_id IS NULL) OR
  (actor_type = 'api_client' AND actor_api_client_id IS NOT NULL AND actor_user_id IS NULL) OR
  (actor_type IN ('system', 'webhook') AND actor_user_id IS NULL AND actor_api_client_id IS NULL));

CREATE TRIGGER tg_audit_logs__append_only BEFORE UPDATE OR DELETE ON audit_logs
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
CREATE TRIGGER tg_activity_logs__append_only BEFORE UPDATE OR DELETE ON activity_logs
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
CREATE TRIGGER tg_domain_events__append_only BEFORE UPDATE OR DELETE ON domain_events
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

ALTER TABLE outbox_messages ADD CONSTRAINT ck_outbox_messages__attempts CHECK (attempts >= 0);

-- --- idempotency (contract §3) -------------------------------------------------------------
ALTER TABLE idempotency_keys
  ADD CONSTRAINT ck_idempotency_keys__sha256 CHECK (octet_length(request_sha256) = 32),
  ADD CONSTRAINT ck_idempotency_keys__completed CHECK (status = 'in_progress' OR response_status IS NOT NULL);

-- --- notifications (D-143, D-144) ----------------------------------------------------------
CREATE UNIQUE INDEX ux_notification_routes__matrix
  ON notification_routes (event_type, audience, COALESCE(staff_team_id, 0), channel);
