ALTER TABLE notification_preferences ADD CONSTRAINT ck_notification_preferences__transactional_email
  CHECK (NOT (channel = 'email' AND category = 'transactional' AND NOT enabled));

-- --- business calendars (D-161) ------------------------------------------------------------
ALTER TABLE business_calendars
  ADD CONSTRAINT ck_business_calendars__weekend_days CHECK (weekend_days IS NOT NULL AND weekend_days <@ ARRAY[0, 1, 2, 3, 4, 5, 6]::smallint[]),
  ADD CONSTRAINT ck_business_calendars__factory CHECK ((kind = 'factory') = (factory_id IS NOT NULL)),
  ADD CONSTRAINT ck_business_calendars__not_own_base CHECK (base_calendar_id IS NULL OR base_calendar_id <> id);
-- Observance only qualifies holidays; closures and extra working days apply to everyone.
ALTER TABLE business_calendar_days ADD CONSTRAINT ck_business_calendar_days__observance
  CHECK (kind = 'holiday' OR observance = 'all');

-- --- embeddings (ADR-0001) -----------------------------------------------------------------
-- The HNSW indexes are created with the first AI feature: Prisma cannot model them (the drift check
-- would drop them), the tables stay empty until then, and the dimension may still change (Q-8).
